# Fix: convert all numpy types in results before json.dump
import json, numpy as np

def convert_numpy(obj):
    if isinstance(obj, dict):
        return {k: convert_numpy(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [convert_numpy(v) for v in obj]
    elif isinstance(obj, (np.bool_,)):
        return bool(obj)
    elif isinstance(obj, (np.integer,)):
        return int(obj)
    elif isinstance(obj, (np.floating,)):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    return obj

# Rewrite the script's save section
import re
with open('tost_cls_traj.py') as f:
    code = f.read()

# Replace the json.dump line
code = code.replace(
    'json.dump(results, f, indent=2, default=lambda o: bool(o) if hasattr(o, \"__bool__\") and type(o).__module__ == \"numpy\" else o)',
    'json.dump(results, f, indent=2)'
)

# Add convert_numpy helper and use it
convert_func = '''
def convert_numpy(obj):
    if isinstance(obj, dict):
        return {str(k): convert_numpy(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [convert_numpy(v) for v in obj]
    elif hasattr(obj, \"item\"):
        return obj.item()
    return obj

'''

# Insert before main
code = code.replace('def main():', convert_func + 'def main():')

# Change json.dump to use convert_numpy
code = code.replace(
    'json.dump(results, f, indent=2)',
    'json.dump(convert_numpy(results), f, indent=2)'
)

with open('tost_cls_traj.py', 'w') as f:
    f.write(code)
print('Fixed')
"

